-- EHS One · 0020 · Biblioteca de modelos, inspeção de equipamentos e assinatura
-- Biblioteca global de modelos (começa com 30 checklists de equipamentos): toda empresa
-- vê e copia para editar. Inspeção ganha TAG, hora, documento do inspetor e empresa;
-- "Não" exige observação; assinatura desenhada com nome, documento, data e hora,
-- IP, aparelho e hash, que não pode mais ser alterada.
--
-- Pode rodar mais de uma vez: se já foi rodado neste banco, não faz nada.

do $migracao$
begin
  if to_regclass('public.inspection_signatures') is not null then
    raise notice 'Já rodado antes: nada a fazer.';
    return;
  end if;
  execute $sql$

/* ---------------- Biblioteca de modelos (global) ---------------- */

create table public.model_library (
  id           uuid primary key default gen_random_uuid(),
  kind         text not null check (kind in ('checklist', 'apr', 'pt', 'dds', 'treinamento', 'documento', 'outro')),
  code         text not null unique,
  title        text not null check (length(trim(title)) > 0),
  category     text,
  sort         integer not null default 0,
  content      jsonb not null default '{}'::jsonb,
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index model_library_kind_idx on public.model_library(kind, category, sort);
create trigger model_library_touch before update on public.model_library
  for each row execute function public.touch_updated_at();
alter table public.model_library enable row level security;
grant select, insert, update, delete on public.model_library to authenticated;
create policy model_library_select on public.model_library for select to authenticated using (active or public.is_platform_admin());
create policy model_library_write on public.model_library for all to authenticated
  using (public.is_platform_admin()) with check (public.is_platform_admin());

