/* ---------------- Modelos da empresa e inspeções ---------------- */

alter table public.checklist_templates
  add column if not exists library_code text,
  add column if not exists equipment text,
  add column if not exists signature_roles text[] not null default '{}';

alter table public.inspections
  add column if not exists equipment_tag text,
  add column if not exists inspected_at time,
  add column if not exists inspector_document text,
  add column if not exists company_name text;

-- Concluir passa a exigir observação em todo "Não" (não conforme).
create or replace function public.conclude_inspection(p_id uuid)
returns integer language plpgsql security definer set search_path = public as $f$
declare
  insp record;
  faltam integer;
  sem_obs integer;
  plano uuid;
  nc record;
  aid uuid;
  n integer := 0;
begin
  if not public.can_edit_inspection(p_id) then
    raise exception 'Sem permissão para concluir esta inspeção.';
  end if;
  select i.*, t.name as modelo, s.name as setor into insp
  from public.inspections i
  join public.checklist_templates t on t.id = i.template_id
  left join public.sectors s on s.id = i.sector_id
  where i.id = p_id for update of i;
  if insp.status = 'concluida' then return 0; end if;
  select count(*) into faltam from public.inspection_answers where inspection_id = p_id and answer is null;
  if faltam > 0 then
    raise exception 'Responda todas as perguntas antes de concluir (faltam %).', faltam;
  end if;
  select count(*) into sem_obs from public.inspection_answers
  where inspection_id = p_id and answer = 'nao_conforme' and coalesce(trim(comment), '') = '';
  if sem_obs > 0 then
    raise exception 'Escreva a observação de cada item com "Não" antes de concluir (faltam %).', sem_obs;
  end if;

  for nc in
    select id, question, comment from public.inspection_answers
    where inspection_id = p_id and answer = 'nao_conforme' and action_id is null order by position
  loop
    if plano is null then
      select id into plano from public.action_plans
      where organization_id = insp.organization_id and origin = 'inspecao' and origin_ref = p_id
        and status in ('aberto', 'em_andamento') limit 1;
      if plano is null then
        insert into public.action_plans (organization_id, title, origin, origin_ref, due_date)
        values (insp.organization_id,
                format('I-%s · %s%s%s · %s', lpad(insp.number::text, 4, '0'), insp.modelo,
                       coalesce(' ' || insp.equipment_tag, ''),
                       coalesce(' (' || insp.setor || ')', ''), to_char(insp.inspected_on, 'DD/MM/YYYY')),
                'inspecao', p_id, current_date + 15)
        returning id into plano;
      end if;
    end if;
    insert into public.actions (organization_id, plan_id, origin, origin_ref, problem, action, due_date)
    values (insp.organization_id, plano, 'inspecao', p_id,
            nc.question || coalesce(' — ' || nc.comment, ''),
            'Corrigir a não conformidade apontada na inspeção', current_date + 15)
    returning id into aid;
    update public.inspection_answers set action_id = aid where id = nc.id;
    n := n + 1;
  end loop;

  update public.inspections set status = 'concluida', concluded_at = now() where id = p_id;
  return n;
end;
$f$;

/* ---------------- Assinaturas da inspeção (imutáveis) ---------------- */

create table public.inspection_signatures (
  id               uuid primary key default gen_random_uuid(),
  organization_id  uuid not null references public.organizations(id) on delete cascade,
  inspection_id    uuid not null references public.inspections(id) on delete cascade,
  role             text not null check (length(trim(role)) > 0),
  signer_name      text not null check (length(trim(signer_name)) > 1),
  signer_document  text not null check (length(trim(signer_document)) > 0),
  image            text not null check (image like 'data:image/png;base64,%' and length(image) < 300000),
  signed_at        timestamptz not null default now(),
  ip               text,
  device           text,
  hash             text not null default '',
  user_id          uuid references auth.users(id) default auth.uid(),
  unique (inspection_id, role)
);
alter table public.inspection_signatures enable row level security;
grant select, insert on public.inspection_signatures to authenticated;
create policy inspection_signatures_select on public.inspection_signatures for select
  using (public.can_see_inspection(inspection_id));
create policy inspection_signatures_insert on public.inspection_signatures for insert
  with check (public.can_see_inspection(inspection_id) and public.is_member(organization_id) and user_id = auth.uid());

-- Ao assinar: confere empresa e situação, carimba data, e calcula o hash (SHA-256) do
-- conteúdo assinado: inspeção, respostas e dados da assinatura.
create or replace function public.inspection_signature_stamp()
returns trigger language plpgsql security definer set search_path = public as $f$
declare insp record; respostas text;
begin
  select organization_id, status, number, equipment_tag, inspected_on into insp
  from public.inspections where id = new.inspection_id;
  if insp.organization_id is distinct from new.organization_id then
    raise exception 'registro de outra empresa';
  end if;
  if insp.status <> 'concluida' then
    raise exception 'Conclua a inspeção antes de assinar.';
  end if;
  new.signed_at := now();
  new.user_id := auth.uid();
  new.ip := left(new.ip, 100);
  new.device := left(new.device, 300);
  select string_agg(position || ':' || question || '=' || coalesce(answer, '') || '|' || coalesce(comment, ''), ';' order by position)
    into respostas from public.inspection_answers where inspection_id = new.inspection_id;
  new.hash := encode(sha256(convert_to(concat_ws('#',
    new.inspection_id, insp.number, insp.equipment_tag, insp.inspected_on, respostas,
    new.role, new.signer_name, new.signer_document, new.signed_at, new.ip, new.device, new.image), 'UTF8')), 'hex');
  return new;
end;
$f$;
create trigger inspection_signatures_stamp before insert on public.inspection_signatures
  for each row execute function public.inspection_signature_stamp();
create trigger inspection_signatures_audit after insert on public.inspection_signatures
  for each row execute function public.audit_row();

-- Depois de assinada, a inspeção (e suas respostas e assinaturas) não muda mais.
-- Só a exclusão da empresa inteira apaga.
create or replace function public.inspection_signed_lock()
returns trigger language plpgsql security definer set search_path = public as $f$
declare insp uuid; org uuid;
begin
  if tg_table_name = 'inspections' then insp := old.id; org := old.organization_id;
  else insp := old.inspection_id; org := old.organization_id; end if;
  if not exists (select 1 from public.organizations where id = org) then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_table_name = 'inspection_answers' and tg_op = 'UPDATE' then
    if (new.answer, new.comment, new.photo_path, new.question)
       is not distinct from (old.answer, old.comment, old.photo_path, old.question) then
      return new; -- só o vínculo com a ação mudou
    end if;
  end if;
  if exists (select 1 from public.inspection_signatures s where s.inspection_id = insp) then
    raise exception 'Inspeção assinada: não pode mais ser alterada nem excluída.';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$f$;
create trigger inspections_signed_lock before update or delete on public.inspections
  for each row execute function public.inspection_signed_lock();
create trigger inspection_answers_signed_lock before update or delete on public.inspection_answers
  for each row execute function public.inspection_signed_lock();
create trigger inspection_signatures_lock before update or delete on public.inspection_signatures
  for each row execute function public.inspection_signed_lock();

revoke all on function public.inspection_signature_stamp() from public, anon;
revoke all on function public.inspection_signed_lock() from public, anon;

  $sql$;
end $migracao$;

select '0020: pronto no banco' as resultado where to_regclass('public.inspection_signatures') is not null;
